select id, 'bekit', 'drag_drop', 'Амалды ажырат', 'Әр жағдайда қандай амал керек екенін ажырат.', jsonb_build_object('items', jsonb_build_array(jsonb_build_object('label', '3 л + 4 л қосу', 'group', 'a'), jsonb_build_object('label', '10 л-дан 4 л құю', 'group', 'b'), jsonb_build_object('label', '5 л + 2 л қосу', 'group', 'a'), jsonb_build_object('label', '8 л-дан 3 л алу', 'group', 'b')), 'groupALabel', 'Құю (қосу)', 'groupBLabel', 'Құю (азайту)'), 3 from public.topics where title = 'Өлшеу және құю' and grade = 2 and track = 'logic';

insert into public.lesson_blocks (topic_id, stage, block_type, title, content, configuration, sort_order)
select id, 'bekit', 'matching', 'Жұптарды сәйкестендір', 'Қосындысы 10 болатын литр сандарын сәйкестендір:', jsonb_build_object('pairs', jsonb_build_array(jsonb_build_array(3,7), jsonb_build_array(4,6), jsonb_build_array(2,8), jsonb_build_array(5,5))), 4 from public.topics where title = 'Өлшеу және құю' and grade = 2 and track = 'logic';

